previewCss:
.darma-loader-darma-b15-bamboo-segments { --accent: var(--loader-color, #166534); --accent-2: var(--loader-secondary-color, #86efac); width: calc(var(--loader-size, 116px) * .56); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b15-bamboo-segments span { position: absolute; left: 30%; width: 40%; height: 16%; border-radius: 5px; background: linear-gradient(90deg, var(--accent-2), var(--accent) 70%); box-shadow: 0 2px 0 color-mix(in srgb, #000 25%, transparent); transform-origin: 50% 100%; transform: scaleY(0); animation: darma-loader-darma-b15-bamboo-segments-bam-grow calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b15-bamboo-segments span:nth-of-type(1) { bottom: 3%; }
.darma-loader-darma-b15-bamboo-segments span:nth-of-type(2) { bottom: 22%; animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b15-bamboo-segments span:nth-of-type(3) { bottom: 41%; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b15-bamboo-segments span:nth-of-type(4) { bottom: 60%; animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b15-bamboo-segments span:nth-of-type(5) { bottom: 79%; animation-delay: calc(var(--loader-speed, 1s) * .72); }
.darma-loader-darma-b15-bamboo-segments i { position: absolute; width: 34%; height: 11%; border-radius: 60% 6% 60% 6%; background: var(--accent-2); transform: scale(0); animation: darma-loader-darma-b15-bamboo-segments-bam-leaf calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
.darma-loader-darma-b15-bamboo-segments i:nth-of-type(1) { left: 66%; bottom: 46%; animation-delay: calc(var(--loader-speed, 1s) * .5); }
.darma-loader-darma-b15-bamboo-segments i:nth-of-type(2) { left: 0; bottom: 66%; border-radius: 6% 60% 6% 60%; animation-delay: calc(var(--loader-speed, 1s) * .7); }
@keyframes darma-loader-darma-b15-bamboo-segments-bam-grow { 0%, 8% { transform: scaleY(0); opacity: 0; } 26%, 70% { transform: scaleY(1); opacity: 1; } 92%, 100% { transform: scaleY(0); opacity: 0; } }
@keyframes darma-loader-darma-b15-bamboo-segments-bam-leaf { 0%, 20% { transform: scale(0); opacity: 0; } 40%, 70% { transform: scale(1); opacity: 1; } 90%, 100% { transform: scale(0); opacity: 0; } }

